const BlockType = require('../../extension-support/block-type')
const Serial = require('../../io/serial.js')

const blockIconURI = 'data:image/svg+xml;base64,';

class arduino {
	constructor (runtime, extensionId) {
		this._runtime = runtime
		this._extensionId = extensionId
		this._serial = null
		this._runtime.registerPeripheralExtension(extensionId, this)
		this.reset = this.reset.bind(this)
		this._onConnect = this._onConnect.bind(this)
		this._onMessage = this._onMessage.bind(this)
		this._pollValues = this._pollValues.bind(this)
    this.message = null
    this._messageObj = null
	}

  scan(){
    if(this._serial) this._serial.disconnectPeripheral()
    this._serial = new Serial(
      this._runtime, 
      this._extensionId,
			this._onConnect,
      this._onMessage
    )
  }

  connect(id){
    if (this._serial) this._serial.connectPeripheral(id)
  }

	disconnect () {
		if (this._serial) {
			this._serial.disconnectPeripheral()
			// this.reset();
		}
	}

	reset () {

	}

	isConnected () {
		if(this._serial){
			return this._serial.connected
		} else return false
	}    

  _onConnect () {
    
  }

  _pollValues () {

  }

  _onMessage (value) {
    this.message = value
    //Vulnerabilidad complicada
    try {
      this._messageObj = JSON.parse(value)

      this.value = this._messageObj.value
      this.btn = this._messageObj.button

      this.temp = this._messageObj.temp

    } catch (e) {
      this._messageObj = {
        error: "Error al parsear el mensaje"
      }  
    }
  }

  isBtnPressed = () => this.btn === 1
}

class Scratch3PlayIoTBlocks{
    static get extensionId () {
        return 'playiot'
    }

    constructor (runtime) {
        this.runtime = runtime
        this._peripheral = new arduino(runtime, Scratch3PlayIoTBlocks.extensionId)
    }

    getInfo () {
        return {
            id: Scratch3PlayIoTBlocks.extensionId,
            name: 'PlayGo',
            blockIconURI: blockIconURI,
            menuIconURI: blockIconURI,
            showStatusButton: true,
						blocks: [
              {
                opcode: 'whenBtnPressed',
                text: "Cuando se presione el botón",
                blockType: BlockType.HAT,
              }, {
                opcode: 'readSerial',
                text: "Obtener valor",
                blockType: BlockType.REPORTER
              }, {
                opcode: 'readTemp',
                text: "Temp example",
                blockType: BlockType.REPORTER
              }
						]
        }
    }

		readSerial = () => this._peripheral.value

    whenBtnPressed = () => this._peripheral.isBtnPressed()

    readTemp = () => this._peripheral.temp
}

module.exports = Scratch3PlayIoTBlocks
